package com.hbm.client.coolingtower;
import com.hbm.machine.coolingtower.*;import com.hbm.client.gui.font.LegacyFonts;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;
/** Original fluid look overlay uses user's requested resource bars; same real tanks as Jade. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class CoolingTowerOverlay {
 @SubscribeEvent public static void render(RenderGuiEvent.Post event){var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.level==null||!(mc.hitResult instanceof BlockHitResult hit))return;var block=mc.level.getBlockState(hit.getBlockPos()).getBlock();var pos=block instanceof CoolingTowerBlock tower?tower.findCore(mc.level,hit.getBlockPos()):hit.getBlockPos();if(pos==null||!(mc.level.getBlockEntity(pos) instanceof CoolingTowerBlockEntity machine))return;var g=event.getGuiGraphics();int x=g.guiWidth()/2+8,y=g.guiHeight()/2-10;var font=LegacyFonts.get();g.drawString(font,Component.translatable("block.hbm."+machine.kind.id),x,y,0xffff00,true);y+=12;for(var tank:machine.tanks){int width=180;double ratio=(double)tank.getFill()/tank.getMaxFill();g.fill(x+1,y+1,x+1+(int)((width-2)*Math.max(0,Math.min(1,ratio))),y+11,0xa0000000|tank.getTankType().getColor()&0xffffff);g.drawString(font,tank.getTankType().displayName().copy().append(" "+tank.getFill()+"/"+tank.getMaxFill()+"mB"),x+2,y+1,0xffffff,true);y+=14;}}
 private CoolingTowerOverlay(){}
}
